class IntConverter:
    """Convert string to integer with auto base detection from prefix."""
    def __call__(self, string, match):
        # R6: Support hex, binary, octal with optional base argument
        # Auto-detect base from prefix (0x, 0b, 0o)
        if len(string) > 2 and string[0] in '+-' and string[2] == '0':
            rest = string[2]
            if rest in 'bB':
                base = 2
            elif rest in 'oO':
                base = 8
            elif rest in 'xX':
                base = 16
            else:
                base = 10
        elif len(string) > 1 and string[0] == '0':
            rest = string[1]
            if rest in 'bB':
                base = 2
            elif rest in 'oO':
                base = 8
            elif rest in 'xX':
                base = 16
            else:
                base = 10
        else:
            base = 10

        # Parse sign
        if string.startswith('-'):
            sign = -1
            s = string[1:]
        elif string.startswith('+'):
            sign = 1
            s = string[1:]
        else:
            sign = 1
            s = string

        # Strip leading '0' for non-hex prefixes
        if len(s) > 1 and s[0] == '0' and s[1] in 'bBoOxX':
            s = s[2:]

        return sign * int(s, base)


